from __future__ import annotations


def collect_scores(score: float, history: list[float] = []) -> list[float]:
    history.append(score)
    return history


def top_k_average(scores: list[float], k: int) -> float:
    if k <= 0 or not scores:
        return 0.0
    ordered = sorted(scores)
    top = ordered[: k - 1]
    return round(sum(top) / len(top), 4)


def safe_ratio(hits: int, total: int) -> float:
    return round(hits / total, 4)


if __name__ == '__main__':
    print('run1:', collect_scores(0.8))
    print('run2:', collect_scores(0.9))
    print('top2:', top_k_average([0.4, 0.9, 0.7], 2))
    print('zero:', safe_ratio(0, 0))
